    qrGenerating: 'Đang tạo mã QR...',
    guideTab: 'Kiến tạo',
    guideTabTitle: 'Tạo sản phẩm dạy và học tương tác với AI',
    guideTitle: 'Tạo ra sản phẩm dạy và học tương tác',
    guideIntro: 'Không chỉ “chạy được” — mà phải tạo ra trải nghiệm học tập có giá trị. Thước đo cuối cùng: giá trị học tập, KHÔNG phải độ phức tạp của công nghệ. Lộ trình 8 bước (Bước 1–Bước 8) trong một buổi: từ vấn đề học thật của học trò đến link web dùng chung. Không cần biết lập trình – chỉ cần ý tưởng sư phạm!',
    guideStep1T: 'Bước 1 • Xác định vấn đề & hình thức',
    guideStep1D: 'Chọn MỘT bài dạy cụ thể, nêu khó khăn thật của học sinh (hiểu? nhìn? luyện? trải nghiệm?), nguồn kiến thức và mục tiêu học tập. Chọn MỘT hình thức chính: mô phỏng, mô hình tương tác, trò chơi, game hóa, thí nghiệm ảo, tình huống ra quyết định. Đầu ra: bảng mô tả Vấn đề – Mục tiêu – Hình thức.',
    guideStep2T: 'Bước 2 • Thu thập thông tin (hai đội)',
    guideStep2D: 'Nhóm chia thành hai đội. Đội ở bàn đóng vai HỌC SINH: viết cảm giác khi học khó hiểu, nêu mong muốn, đề xuất cách học vui, dễ hiểu. Đội đi đóng vai GIÁO VIÊN: đến các nhóm khác hỏi thật nhanh, ghi câu trả lời hay, mang về. Vòng 1 • 5 phút → đổi đội → Vòng 2 • 5 phút.',
    guideStep3T: 'Bước 3 • Tổng hợp & tải Prompt Guide',
    guideStep3D: 'Gom phiếu, thống nhất MỘT chủ đề học sinh cần nhất; viết mô tả bài dạy ngắn gọn (lớp, bài, mục tiêu, khó khăn). Tải Prompt Guide v24 (.md) tại webshare-pmca.vercel.app về máy.',
    guideStep4T: 'Bước 4 • Trao quyền cho AI',
    guideStep4D: 'Mở ChatGPT hoặc Gemini (bản miễn phí là đủ). Gửi file .md và trao quyền: “Làm theo tài liệu, hỏi tôi nếu cần”. Trả lời câu hỏi của AI càng đầy đủ, đúng thật càng tốt. Đầu ra: 01 file .md MỚI — bản thiết kế cho AI Studio (vd: SIM_DINH_LUAT_I_NEWTON_SPEC.md).',
    guideStep5T: 'Bước 5 • Chế tạo app với AI Studio',
    guideStep5D: 'Mở Google AI Studio, đăng nhập bằng tài khoản Google. Nạp toàn bộ nội dung file .md mới vào ô lệnh. Chọn Web App rồi bấm Build — AI tự viết mã, bạn tự chạy thử. Xem thử & ra thêm lệnh cho đến khi ưng ý. Đầu ra: app tương tác CHẠY ĐƯỢC ngay trong AI Studio.',
    guideStep6T: 'Bước 6 • Kiểm tra & cải tiến',
    guideStep6D: 'Mở được ngay trên trình duyệt (cả điện thoại), học sinh biết ngay phải làm gì, có phản hồi đúng/sai/điểm/gợi ý, nội dung đúng chuẩn môn học. Chưa ưng? Ra thêm lệnh để sửa ngay trong AI Studio — không cần biết lập trình.',
    guideStep7T: 'Bước 7 • Lưu mã vào GitHub',
    guideStep7D: 'AI Studio → Export / Get Code để tải mã ra máy. GitHub → New repository, đặt tên rõ ràng (vd: ai-quiz-lop5), chọn Public. GitHub → Upload files: kéo toàn bộ file mã vào → Commit changes. Lưu ý: dùng chung một email cho AI Studio, GitHub và Vercel.',
    guideStep8T: 'Bước 8 • Xuất bản link web (Vercel)',
    guideStep8D: 'Vercel → Add New Project, kết nối tài khoản GitHub → Import repository → chọn đúng repo vừa tạo → Deploy. Vercel tự dựng và cấp link [tên].vercel.app — mở thử trên điện thoại. Sửa sau đó: link không đổi, Vercel tự cập nhật.',
    guideControlTitle: 'Cách file này "điều khiển" AI',
    guideControlText: 'File hướng dẫn chứa quy trình chuẩn từ ý tưởng đến web: lắng nghe vấn đề học sinh → thu kiến thức nguồn → xác định mục tiêu → thiết kế trải nghiệm → viết tài liệu ROM → tạo prototype → kiểm tra → xuất bản lên GitHub & Vercel. Bạn không cần biết lập trình.',
    guideDownloadTitle: 'Tải Prompt Guide v24 (.md)',
    guideDownloadDesc: 'Tải file SIMBOT_UNIVERSAL_PROMPT_GUIDE_V24.md về máy hoặc mở trong tab mới. File này là “bộ não” dẫn dắt toàn bộ hội thoại với AI ở các bước tiếp theo.',
    guideDownloadBtn: 'Tải Prompt Guide v24 (.md)',
    guideUploadTitle: '2. Đưa file lên ChatGPT / Gemini',
    guideUploadDesc: 'Mở một cuộc trò chuyện mới, tải file hoặc dán toàn bộ nội dung lên. AI sẽ tự nhận ra đây là bộ quy chuẩn và tự động bắt đầu (AUTO-START).',
    guideQaTitle: '3. Trao quyền và trả lời câu hỏi',
    guideQa1: 'AI tự điều khiển quy trình: nó hỏi trước, bạn chỉ trả lời ngắn gọn những gì mình biết.',
    guideQa2: 'Không cần ra lệnh "hãy tạo mô phỏng" — file đã giao quyền cho AI tự bắt đầu.',
    guideQa3: 'Bạn giữ quyền kiểm soát nội dung, kiến thức nguồn và quyết định cuối cùng.',
    guideQa4: 'AI hướng dẫn từng bước một và chờ bạn báo kết quả; chỉ đưa bước tiếp theo khi bạn sẵn sàng.',
    guideTipsTitle: '4. Tạo mô phỏng / game từ file gốc',
    guideTip1: 'Từ file gốc, bạn có thể yêu cầu AI tạo ra các file .md riêng (ROM) cho từng bài học, trò chơi hoặc bài dạy.',
    guideTip2: 'AI sẽ viết ROM đủ chi tiết để một coding agent triển khai mà không cần đoán quyết định cốt lõi.',
    guideTip3: 'Mô phỏng, game hay bài dạy đều đi qua cùng chuỗi: ý tưởng → ROM → prototype → thử nghiệm → xuất bản.',
    guideToolsTitle: 'Công cụ: AI Studio → GitHub → Vercel',
    guideToolsDesc: 'Ba công cụ miễn phí đi cùng lộ trình — Bước 5 AI Studio tạo app, Bước 7 GitHub lưu mã, Bước 8 Vercel xuất bản link web:',
    guideToolStudio: 'Google AI Studio',
    guideToolStudioDesc: 'Bước 5 – Nơi nạp file .md mới, chọn Web App, bấm Build để tạo app tương tác chạy được ngay.',
    guideToolGit: 'GitHub',
    guideToolGitDesc: 'Bước 7 – Nơi lưu mã nguồn trong repository Public để chuẩn bị xuất bản.',
    guideToolVercel: 'Vercel',
    guideToolVercelDesc: 'Bước 8 – Kết nối repository GitHub, tự dựng và cấp link web dùng chung.',
    guideToolStudioSignup: 'Dùng tài khoản Google miễn phí của bạn để đăng nhập AI Studio. Nhớ dùng CHUNG EMAIL này cho cả GitHub và Vercel.',
    guideToolStudioLogin: 'Truy cập aistudio.google.com → bấm "Sign in" → chọn tài khoản Google của bạn để vào trang chính.',
    guideToolGitSignup: 'Tạo tài khoản tại github.com/signup bằng CHÍNH EMAIL đã dùng cho AI Studio — xác minh qua hộp thư.',
    guideToolGitLogin: 'Mở github.com → bấm "Sign in" → nhập email/tên người dùng và mật khẩu. Nên bật xác thực hai yếu tố (2FA).',
    guideToolVercelSignup: 'Tạo tài khoản tại vercel.com → bấm "Sign Up" → nên chọn "Continue with GitHub" để liên kết ngay (cùng email chung).',
