    amLastSync: 'Last sync: ',
    qrGenerating: 'Generating QR code...',
    guideTab: 'Guide',
    guideTabTitle: 'Create interactive teaching & learning products with AI',
    guideTitle: 'Create interactive learning products',
    guideIntro: 'Not just “it runs” — but creating a learning experience that has value. The ultimate measure: learning value, NOT technical complexity. An 8-step journey (Step 1–Step 8) in one session: from your students’ real learning problem to a shared web link. No programming needed – just pedagogical ideas!',
    guideStep1T: 'Step 1 • Identify the problem & format',
    guideStep1D: 'Choose ONE specific lesson, state your students’ real difficulty (understand? see? practice? experience?), the knowledge source and the learning objective. Choose ONE main format: simulation, interactive model, game, gamification, virtual lab, decision scenario. Output: a Problem – Objective – Format description sheet.',
    guideStep2T: 'Step 2 • Gather information (two teams)',
    guideStep2D: 'Split the group into two teams. The team at the table plays STUDENTS: write down how it feels when the lesson is hard to understand, express wishes, suggest fun and easy ways to learn. The roving team plays TEACHERS: quickly ask the other groups, note the best answers, bring them back. Round 1 • 5 minutes → swap → Round 2 • 5 minutes.',
    guideStep3T: 'Step 3 • Synthesize & download Prompt Guide',
    guideStep3D: 'Collect the sheets, agree on ONE topic students need most; write a short lesson description (grade, lesson, objective, difficulty). Download Prompt Guide v24 (.md) at webshare-pmca.vercel.app to your device.',
    guideStep4T: 'Step 4 • Empower the AI',
    guideStep4D: 'Open ChatGPT or Gemini (the free version is enough). Send the .md file and give it the lead: “Follow the document, ask me if needed”. Answer the AI’s questions as fully and truthfully as you can. Output: 01 NEW .md file — the design blueprint for AI Studio (e.g.: SIM_DINH_LUAT_I_NEWTON_SPEC.md).',
    guideStep5T: 'Step 5 • Build the app with AI Studio',
    guideStep5D: 'Open Google AI Studio, sign in with your Google account. Load the full content of the new .md file into the command box. Choose Web App then click Build — the AI writes the code, you run it right away. Preview and give more commands until you’re happy. Output: an interactive app that RUNS right in AI Studio.',
    guideStep6T: 'Step 6 • Test & improve',
    guideStep6D: 'Opens right in the browser (including phone), students know immediately what to do, there is right/wrong/score/hint feedback, content matches subject standards. Not happy? Give more commands to fix it right in AI Studio — no programming needed.',
    guideStep7T: 'Step 7 • Save code to GitHub',
    guideStep7D: 'AI Studio → Export / Get Code to download the code to your device. GitHub → New repository, give a clear name (e.g.: ai-quiz-lop5), choose Public. GitHub → Upload files: drag all the code files in → Commit changes. Note: use the SAME email for AI Studio, GitHub and Vercel.',
    guideStep8T: 'Step 8 • Publish web link (Vercel)',
    guideStep8D: 'Vercel → Add New Project, connect your GitHub account → Import repository → choose the repo you just created → Deploy. Vercel builds it and gives you a link [name].vercel.app — try it on your phone. Editing later: the link stays the same, Vercel auto-updates.',
    guideControlTitle: 'How this file "drives" the AI',
    guideControlText: 'The guide file contains the standard process from idea to web: listen to the student problem → gather source knowledge → define objectives → design the experience → write the ROM → build the prototype → test → publish on GitHub & Vercel. No programming needed.',
    guideDownloadTitle: 'Download Prompt Guide v24 (.md)',
    guideDownloadDesc: 'Download the SIMBOT_UNIVERSAL_PROMPT_GUIDE_V24.md file to your device or open it in a new tab. This file is the “brain” that guides the whole conversation with the AI in the next steps.',
    guideDownloadBtn: 'Download Prompt Guide v24 (.md)',
    guideUploadTitle: '2. Give the file to ChatGPT / Gemini',
    guideUploadDesc: 'Start a new chat, upload the file or paste the whole content. The AI recognizes it as the standards pack and auto-starts (AUTO-START).',
    guideQaTitle: '3. Grant control and answer questions',
    guideQa1: 'The AI drives the workflow itself: it asks first, you just answer concisely with what you know.',
    guideQa2: 'No need to command "create a simulation" — the file already empowers the AI to start on its own.',
    guideQa3: 'You keep control of the content, source knowledge and final decisions.',
    guideQa4: 'The AI guides one step at a time and waits for your results; it only moves to the next step when you are ready.',
    guideTipsTitle: '4. Create simulations / games from the original file',
    guideTip1: 'From the original file, you can ask the AI to produce separate .md files (ROMs) for each lesson, game or lesson plan.',
    guideTip2: 'The AI writes the ROM in enough detail that a coding agent can implement it without guessing core decisions.',
    guideTip3: 'Simulations, games and lesson plans all follow the same chain: idea → ROM → prototype → test → publish.',
    guideToolsTitle: 'Tools: AI Studio → GitHub → Vercel',
    guideToolsDesc: 'Three free tools along the journey — Step 5 AI Studio builds the app, Step 7 GitHub stores the code, Step 8 Vercel publishes the web link:',
    guideToolStudio: 'Google AI Studio',
    guideToolStudioDesc: 'Step 5 – Load the new .md file, choose Web App, click Build to create an interactive app that runs right away.',
    guideToolGit: 'GitHub',
    guideToolGitDesc: 'Step 7 – Store the source code in a Public repository, ready for publishing.',
    guideToolVercel: 'Vercel',
    guideToolVercelDesc: 'Step 8 – Connect your GitHub repository, it builds and provides a shared web link.',
    guideToolStudioSignup: 'Use your free Google account to sign in to AI Studio. Remember to use THIS SAME EMAIL for GitHub and Vercel.',
    guideToolStudioLogin: 'Go to aistudio.google.com → click “Sign in” → choose your Google account to enter the main page.',
    guideToolGitSignup: 'Create an account at github.com/signup using THE SAME EMAIL you used for AI Studio — verify it via your inbox.',
    guideToolGitLogin: 'Open github.com → click “Sign in” → enter your email/username and password. It’s best to enable two-factor authentication (2FA).',
    guideToolVercelSignup: 'Create an account at vercel.com → click “Sign Up” → best to choose “Continue with GitHub” to link right away (same shared email).',
    guideToolVercelLogin: 'Go to vercel.com → click “Log In” → sign in with GitHub/GitLab/Email matching the account you created.',
    guideToolSignupLabel: 'Step 1 · Create account',
    guideToolLoginLabel: 'Step 2 · Sign in',
    guideToolUseLabel: 'Step 3 · How to use',
    guideToolOpenSite: 'Open tool website',
