    guidePrep5: 'Textbook & subject materials',
    guideAccountNote: 'Use the SAME ONE EMAIL for AI Studio, GitHub and Vercel for easy connection: sign up for GitHub and Vercel with the same email you used to create AI Studio.',
    guideGitTitle: 'Details: create GitHub & link Vercel',
    guideGit1: 'Step 7 · AI Studio → “Export / Get Code”: download all the code to your device, unzip if needed.',
    guideGit2: 'Step 7 · GitHub → “+” icon → New repository → give a clear name (e.g.: ai-quiz-lop5) → choose Public → Create repository.',
    guideGit3: 'Step 7 · In the new repo → “uploading an existing file” → Upload files → drag all the code files in → Commit changes.',
    guideGit4: 'Step 8 · Vercel → “Add New Project”, connect your GitHub account → Import repository → choose the repo you just created → Deploy.',
    guideGit5: 'Step 8 · Vercel builds it and gives you a link https://<name>.vercel.app → try it on your phone. Editing later: push to GitHub, the link stays the same, Vercel auto-updates.',
    guideUploadSiteTitle: 'Share the product on this website',
    guideUploadSiteDesc: 'Once you have a simulation website/URL, you can submit it to this sharing site (the "Uploaded" tab) so teachers and students in the community can access, try and share it.',
    guideUploadSiteBtn: 'Submit website',
