    guideTabTitle: 'สร้างผลงานการเรียนรู้แบบโต้ตอบด้วย AI',
    guideTitle: 'สร้างผลิตภัณฑ์การเรียนรู้แบบโต้ตอบ',
    guideIntro: 'ไม่ใช่แค่ “รันได้” — แต่ต้องสร้างประสบการณ์การเรียนรู้ที่มีคุณค่า ตัวชี้วัดสุดท้าย: คุณค่าทางการเรียนรู้ ไม่ใช่ความซับซ้อนของเทคโนโลยี เส้นทาง 8 ขั้นตอน (ขั้นตอนที่ 1–ขั้นตอนที่ 8) ในหนึ่งรอบ: จากปัญหาการเรียนรู้จริงของนักเรียน ไปจนถึงลิงก์เว็บที่ใช้ร่วมกัน ไม่ต้องเขียนโปรแกรม – แค่ต้องมีไอเดียการสอน!',
    guideStep1T: 'ขั้นตอนที่ 1 • ระบุปัญหาและรูปแบบ',
    guideStep1D: 'เลือกบทเรียนเฉพาะ 1 บท ระบุปัญหาจริงของนักเรียน (เข้าใจ? เห็น? ฝึก? สัมผัสประสบการณ์?) แหล่งความรู้ และเป้าหมายการเรียนรู้ เลือกรูปแบบหลัก 1 รูปแบบ: การจำลอง โมเดลแบบโต้ตอบ เกม การทำให้เป็นเกม ห้องทดลองเสมือน สถานการณ์ตัดสินใจ ผลลัพธ์: แผ่นอธิบาย ปัญหา – เป้าหมาย – รูปแบบ',
    guideStep2T: 'ขั้นตอนที่ 2 • เก็บข้อมูล (สองทีม)',
    guideStep2D: 'แบ่งกลุ่มเป็นสองทีม ทีมนั่งที่โต๊ะสวมบทเป็นนักเรียน: เขียนความรู้สึกเมื่อเรียนแล้วงง ระบุความต้องการ เสนอวิธีเรียนที่สนุกและเข้าใจง่าย ทีมเดินสวมบทเป็นครู: ไปถามกลุ่มอื่นอย่างรวดเร็ว จดคำตอบดีๆ แล้วนำกลับมา รอบ 1 • 5 นาที → สลับทีม → รอบ 2 • 5 นาที',
    guideStep3T: 'ขั้นตอนที่ 3 • สรุปข้อมูลและดาวน์โหลด Prompt Guide',
    guideStep3D: 'เก็บแผ่นงาน ตกลงให้เป็น 1 หัวข้อที่นักเรียนต้องการมากที่สุด เขียนคำอธิบายบทเรียนแบบสั้น (ชั้น, บท, เป้าหมาย, ความยาก) ดาวน์โหลด Prompt Guide v24 (.md) ที่ webshare-pmca.vercel.app ไปยังเครื่อง',
    guideStep4T: 'ขั้นตอนที่ 4 • มอบอำนาจให้ AI',
    guideStep4D: 'เปิด ChatGPT หรือ Gemini (เวอร์ชันฟรีก็เพียงพอ) ส่งไฟล์ .md และมอบอำนาจ: “ทำตามเอกสาร ถามฉันถ้าจำเป็น” ตอบคำถามของ AI ให้เต็มที่สุดและถูกต้องที่สุด ผลลัพธ์: ไฟล์ .md ใหม่ 01 ไฟล์ — แบบร่างสำหรับ AI Studio (เช่น SIM_DINH_LUAT_I_NEWTON_SPEC.md)',
    guideStep5T: 'ขั้นตอนที่ 5 • สร้างแอปด้วย AI Studio',
    guideStep5D: 'เปิด Google AI Studio ลงชื่อเข้า ด้วยบัญชี Google โหลดเนื้อหาทั้งหมดของไฟล์ .md ใหม่ลงในช่องคำสั่ง เลือก Web App แล้วกด Build — AI เขียนโค้ดให้ แล้วรันทดสอบเอง ดูตัวอย่างและสั่งเพิ่มจนพอใจ ผลลัพธ์: แอปแบบโต้ตอบที่ทำงานได้ทันทีใน AI Studio',
    guideStep6T: 'ขั้นตอนที่ 6 • ทดสอบและปรับปรุง',
    guideStep6D: 'เปิดได้ทันทีในเบราว์เซอร์ (รวมโทรศัพท์) นักเรียนรู้ทันทีว่าต้องทำอะไร มีการตอบสนอง ถูก/ผิด/คะแนน/คำแนะนำ เนื้อหาตรงมาตรฐานรายวิชา ยังไม่พอใจ? สั่งเพิ่มเพื่อแก้ใน AI Studio ได้ทันที — ไม่ต้องเขียนโปรแกรม',
    guideStep7T: 'ขั้นตอนที่ 7 • บันทึกโค้ดไปที่ GitHub',
