    gsStep3: 'ວາງໂຄ້ດ Code.gs',
    gsStep3Desc: 'ປ່ຽນໄປຫຼັກ "ຊອຟຕ໌ເຄອດ Apps Script" ດ້ານເທິງ, ກົດ "ສຳເນົາໂຄ້ດ". ໃນໂຕແກ້ໄຂ Apps Script ລຶບເນື້ອຫາເກົ່າອອກໝົດແລ້ວວາງໂຄ້ດທັງໝົດ. ກົດບັນທຶກ (Ctrl + S).',
    gsStep4: 'ຕິດຕັ້ງເປັນ Web App',
