    gsStep4Desc5: '• ຜູ້ເຂົ້າເຖິງ (Who has access): ທຸກຄົນ (Anyone) (ຈຳເປັນເພື່ອໃຫ້ເວັບໄຊທ໌ອ່ານຂໍ້ມູນໄດ້ໂດຍບໍ່ຖືກບລັອກ).',
    gsStep5: 'ສຳເນົາ Web App URL ແລະ ວາງໃສ່ WebHub',
    gsStep5Desc: 'ຫຼັງຈາກອະນຸຍາດສິດແລ້ວ Google ຈະໃຫ້ Web App URL ລົງທ້າຍດ້ວຍ /exec. ສຳເນົາລິ້ງນັ້ນວາງໃສ່ຊ່ອງໃນຫຼັກ "ເຊື່ອມຕໍ່ ແລະ ຊິງຄ໌" ແລ້ວກົດບັນທຶກ!',
    gsCodeTitle: 'ຊອຟຕ໌ເຄອດ Code.gs (ປັບປຸງການຈັດກຸ່ມ IsFamous ແລະ CORS ໃຫ້ເໝາະສົມ):',
