    amDeleteWebsite: 'ຢືນຢັນການລຶບເວັບໄຊທ໌',
    amSyncTitle: 'ຊິງຄ໌ຂໍ້ມູນຜ່ານ Google Sheets ແລະ Apps Script',
    amSyncDesc: 'ຂໍ້ມູນເວັບໄຊທ໌ (ທັງຜ່ານອະນຸມັດ, ລໍຖ້າອະນຸມັດ ແລະ mockup) ຈະຖືກເກັບໄວ້ ແລະ ຄວບຄຸມແບບລວມສູນຢູ່ໃນໄຟລ໌ Google Sheets ຂອງທ່ານ. ທ່ານສາມາດກວດສອບໂພສໂດຍກົງໃນ Google Sheets ຫຼື ຢູ່ເວັບໄຊທ໌ນີ້.',
