    amSyncing: 'Menyinkronkan...',
    amFetch: 'Muat data dari Google Sheets',
    amPushCount: 'Kirim {count} situs web ke Sheets',
    amAutoSyncNew: 'Sinkronkan otomatis saat ada postingan baru',
    amLastSync: 'Sinkron terakhir: ',
    qrGenerating: 'Membuat kode QR...',
    guideTab: 'Panduan',
    guideTabTitle: 'Buat produk belajar-mengajar interaktif dengan AI',
    guideTitle: 'Membuat produk belajar mengajar interaktif',
    guideIntro: 'Bukan sekadar "bisa berjalan" — tetapi harus menciptakan pengalaman belajar yang bernilai. Ukuran terakhir: nilai pembelajaran, BUKAN kerumitan teknologi. Alur 8 langkah (Langkah 1–Langkah 8) dalam satu sesi: dari masalah belajar nyata siswa hingga link web yang bisa dibagikan. Tidak perlu bisa coding – cukup punya ide pedagogi!',
    guideStep1T: 'Langkah 1 • Identifikasi masalah & bentuk',
    guideStep1D: 'Pilih SATU pelajaran spesifik, sebutkan kesulitan nyata siswa (memahami? melihat? berlatih? mengalami?), sumber pengetahuan, dan tujuan pembelajaran. Pilih SATU bentuk utama: simulasi, model interaktif, game, gamifikasi, laboratorium virtual, skenario pengambilan keputusan. Hasil: lembar deskripsi Masalah – Tujuan – Bentuk.',
    guideStep2T: 'Langkah 2 • Kumpulkan informasi (dua tim)',
    guideStep2D: 'Bagi kelompok menjadi dua tim. Tim di kursi memerankan SISWA: tulis perasaan saat belajar sulit dipahami, sampaikan keinginan, usulkan cara belajar yang menyenangkan dan mudah dimengerti. Tim berjalan memerankan GURU: cepat mewawancarai kelompok lain, catat jawaban bagus, bawa pulang. Putaran 1 • 5 menit → tukar tim → Putaran 2 • 5 menit.',
    guideStep3T: 'Langkah 3 • Sintesis & unduh Prompt Guide',
    guideStep3D: 'Kumpulkan lembar, sepakati SATU topik yang paling dibutuhkan siswa; tulis deskripsi pelajaran singkat (kelas, bab, tujuan, kesulitan). Unduh Prompt Guide v24 (.md) di webshare-pmca.vercel.app ke perangkat.',
    guideStep4T: 'Langkah 4 • Berdayakan AI',
    guideStep4D: 'Buka ChatGPT atau Gemini (versi gratis cukup). Kirim file .md dan berdayakan: "Ikuti dokumen, tanya saya jika perlu". Jawab pertanyaan AI sepenuh dan senyata mungkin. Hasil: 01 file .md BARU — cetak biru desain untuk AI Studio (mis.: SIM_DINH_LUAT_I_NEWTON_SPEC.md).',
    guideStep5T: 'Langkah 5 • Buat aplikasi dengan AI Studio',
    guideStep5D: 'Buka Google AI Studio, masuk dengan akun Google. Muat seluruh konten file .md baru ke kotak perintah. Pilih Web App lalu klik Build — AI menulis kode sendiri, Anda langsung mencoba menjalankannya. Lihat pratinjau dan beri perintah tambahan sampai puas. Hasil: aplikasi interaktif yang LANGSUNG BERJALAN di AI Studio.',
    guideStep6T: 'Langkah 6 • Uji & perbaiki',
    guideStep6D: 'Langsung terbuka di browser (termasuk ponsel), siswa langsung tahu harus melakukan apa, ada umpan balik benar/salah/nilai/saran, konten sesuai standar mata pelajaran. Belum puas? Beri perintah tambahan untuk memperbaiki langsung di AI Studio — tidak perlu bisa coding.',
    guideStep7T: 'Langkah 7 • Simpan kode ke GitHub',
    guideStep7D: 'AI Studio → Export / Get Code untuk mengunduh kode ke perangkat. GitHub → New repository, beri nama jelas (mis.: ai-quiz-lop5), pilih Public. GitHub → Upload files: tarik semua file kode masuk → Commit changes. Catatan: gunakan SATU email yang sama untuk AI Studio, GitHub, dan Vercel.',
    guideStep8T: 'Langkah 8 • Publikasikan link web (Vercel)',
    guideStep8D: 'Vercel → Add New Project, hubungkan akun GitHub → Import repository → pilih repo yang baru dibuat → Deploy. Vercel membangun sendiri dan memberi link [nama].vercel.app — coba buka di ponsel. Mengubah setelahnya: link tidak berubah, Vercel memperbarui otomatis.',
    guideControlTitle: 'Bagaimana file ini "mengendalikan" AI',
    guideControlText: 'File panduan berisi proses standar dari ide hingga web: mendengarkan masalah siswa → mengumpulkan pengetahuan sumber → menentukan tujuan → mendesain pengalaman → menulis ROM → membuat prototype → menguji → menerbitkan di GitHub & Vercel. Anda tidak perlu bisa coding.',
    guideDownloadTitle: 'Unduh Prompt Guide v24 (.md)',
    guideDownloadDesc: 'Unduh file SIMBOT_UNIVERSAL_PROMPT_GUIDE_V24.md ke perangkat atau buka di tab baru. File ini adalah "otak" yang memandu seluruh percakapan với AI pada langkah-langkah berikutnya.',
    guideDownloadBtn: 'Unduh Prompt Guide v24 (.md)',
    guideUploadTitle: '2. Berikan file ke ChatGPT / Gemini',
    guideUploadDesc: 'Mulai percakapan baru, unggah file atau tempel seluruh isi. AI mengenalinya sebagai paket standar dan mulai otomatis (AUTO-START).',
    guideQaTitle: '3. Berikan kontrol dan jawab pertanyaan',
    guideQa1: 'AI menggerakkan alur kerja sendiri: ia bertanya dulu, Anda cukup menjawab singkat apa yang Anda tahu.',
    guideQa2: 'Tidak perlu memerintah "buat simulasi" — file sudah memberdayakan AI untuk memulai sendiri.',
    guideQa3: 'Anda tetap mengendalikan konten, pengetahuan sumber, dan keputusan akhir.',
    guideQa4: 'AI membimbing satu langkah pada satu waktu dan menunggu hasil Anda; ia lanjut hanya saat Anda siap.',
    guideTipsTitle: '4. Buat simulasi / game dari file asli',
    guideTip1: 'Dari file asli, Anda bisa meminta AI membuat file .md terpisah (ROM) untuk setiap pelajaran, game, atau rencana pembelajaran.',
    guideTip2: 'AI menulis ROM cukup detail sehingga coding agent bisa mengimplementasikannya tanpa menebak.',
    guideTip3: 'Simulasi, game, dan rencana pembelajaran sama-sama melewati rantai yang sama: ide → ROM → prototype → uji → terbitkan.',
    guideToolsTitle: 'Alat: AI Studio → GitHub → Vercel',
    guideToolsDesc: 'Tiga alat gratis yang menyertai alurnya — Langkah 5 AI Studio membuat aplikasi, Langkah 7 GitHub menyimpan kode, Langkah 8 Vercel mempublikasikan link web:',
    guideToolStudio: 'Google AI Studio',
    guideToolStudioDesc: 'Langkah 5 – Tempat memuat file .md baru, pilih Web App, klik Build untuk membuat aplikasi interaktif yang langsung berjalan.',
    guideToolGit: 'GitHub',
    guideToolGitDesc: 'Langkah 7 – Tempat menyimpan kode sumber dalam repository Public untuk siap dipublikasikan.',
    guideToolVercel: 'Vercel',
    guideToolVercelDesc: 'Langkah 8 – Hubungkan repository GitHub, membangun dan memberi link web bersama.',
    guideToolStudioSignup: 'Gunakan akun Google gratis Anda untuk masuk ke AI Studio. Ingat gunakan EMAIL YANG SAMA ini untuk GitHub dan Vercel.',
    guideToolStudioLogin: 'Buka aistudio.google.com → klik "Sign in" → pilih akun Google Anda untuk masuk ke halaman utama.',
    guideToolGitSignup: 'Buat akun di github.com/signup dengan EMAIL YANG SAMA yang dipakai untuk AI Studio — verifikasi melalui email Anda.',
    guideToolGitLogin: 'Buka github.com → klik "Sign in" → masukkan email/nama pengguna dan kata sandi. Sebaiknya aktifkan autentikasi dua faktor (2FA).',
    guideToolVercelSignup: 'Buat akun di vercel.com → klik "Sign Up" → sebaiknya pilih "Continue with GitHub" agar langsung tertaut (email bersama yang sama).',
