    amUrlNote: 'URL ini dicipta apabila anda memilih Terapkan (Deploy) -> Aplikasi web (Web App) dalam Apps Script hamparan anda.',
    amSyncing: 'Menyegerakkan...',
    amFetch: 'Muat data dari Google Sheets',
    amPushCount: 'Hantar {count} laman web ke Sheets',
    amAutoSyncNew: 'Segerak automatik bila ada posting baharu',
    amLastSync: 'Segerak terakhir: ',
    qrGenerating: 'Menjana kod QR...',
    guideTab: 'Panduan',
    guideTabTitle: 'Cipta produk pengajaran-pembelajaran interaktif dengan AI',
    guideTitle: 'Mencipta produk pembelajaran interaktif',
    guideIntro: 'Bukan sekadar "boleh jalan" — tetapi mesti mewujudkan pengalaman pembelajaran yang bernilai. Ukuran akhir: nilai pembelajaran, BUKAN kerumitan teknologi. Laluan 8 langkah (Langkah 1–Langkah 8) dalam satu sesi: daripada masalah pembelajaran sebenar murid kepada pautan web dikongsi. Tidak perlu tahu pengaturcaraan – cukup ada idea pedagogi!',
    guideStep1T: 'Langkah 1 • Kenal pasti masalah & bentuk',
    guideStep1D: 'Pilih SATU pelajaran khusus, nyatakan kesukaran sebenar murid (faham? nampak? latih? alami?), sumber ilmu dan objektif pembelajaran. Pilih SATU bentuk utama: simulasi, model interaktif, permainan, gamifikasi, makmal maya, senario membuat keputusan. Hasil: helaian penerangan Masalah – Objektif – Bentuk.',
    guideStep2T: 'Langkah 2 • Kumpul maklumat (dua pasukan)',
    guideStep2D: 'Bahagi kumpulan kepada dua pasukan. Pasukan di meja memainkan peranan MURID: tulis perasaan ketika belajar yang sukar difahami, nyatakan harapan, cadang cara belajar yang seronok dan mudah. Pasukan bergerak memainkan peranan GURU: tanya kumpulan lain dengan pantas, catat jawapan terbaik, bawa balik. Pusingan 1 • 5 minit → tukar pasukan → Pusingan 2 • 5 minit.',
    guideStep3T: 'Langkah 3 • Rumus & muat turun Prompt Guide',
    guideStep3D: 'Kumpul helaian, pilih SATU topik yang paling diperlukan murid; tulis penerangan pelajaran ringkas (kelas, bab, objektif, kesukaran). Muat turun Prompt Guide v24 (.md) di webshare-pmca.vercel.app ke peranti.',
    guideStep4T: 'Langkah 4 • Beri kuasa kepada AI',
    guideStep4D: 'Buka ChatGPT atau Gemini (versi percuma memadai). Hantar fail .md dan beri kuasa: "Ikut dokumen, tanya saya jika perlu". Jawab soalan AI sepenuh dan setepat mungkin. Hasil: 01 fail .md BARU — pelan reka bentuk untuk AI Studio (cth: SIM_DINH_LUAT_I_NEWTON_SPEC.md).',
    guideStep5T: 'Langkah 5 • Bina aplikasi dengan AI Studio',
    guideStep5D: 'Buka Google AI Studio, log masuk dengan akaun Google. Muat keseluruhan kandungan fail .md baru ke dalam kotak arahan. Pilih Web App kemudian klik Build — AI menulis kod sendiri, anda cuba jalankan. Lihat pratonton & beri arahan lagi sehingga puas hati. Hasil: aplikasi interaktif yang BERJALAN terus dalam AI Studio.',
    guideStep6T: 'Langkah 6 • Uji & penambahbaikan',
    guideStep6D: 'Terus terbuka dalam pelayar (termasuk telefon), murid terus tahu apa yang perlu dilakukan, ada maklum balas betul/salah/markah/cadangan, kandungan memenuhi standard mata pelajaran. Tidak puas? Beri arahan lagi untuk membaiki terus dalam AI Studio — tidak perlu tahu pengaturcaraan.',
    guideStep7T: 'Langkah 7 • Simpan kod ke GitHub',
    guideStep7D: 'AI Studio → Export / Get Code untuk memuat turun kod ke peranti. GitHub → New repository, beri nama yang jelas (cth: ai-quiz-lop5), pilih Public. GitHub → Upload files: seret semua fail kod masuk → Commit changes. Nota: gunakan SATU email yang sama untuk AI Studio, GitHub dan Vercel.',
    guideStep8T: 'Langkah 8 • Terbit pautan web (Vercel)',
    guideStep8D: 'Vercel → Add New Project, sambungkan akaun GitHub → Import repository → pilih repo yang baru dibuat → Deploy. Vercel membina sendiri dan memberi pautan [nama].vercel.app — cuba buka di telefon. Mengubah kemudian: pautan tidak berubah, Vercel mengemas kini automatik.',
    guideControlTitle: 'Bagaimana fail ini "memandu" AI',
    guideControlText: 'Fail panduan mengandungi proses piawaian daripada idea kepada web: mendengar masalah pelajar → mengumpul pengetahuan sumber → menentukan objektif → mereka bentuk pengalaman → menulis ROM → membina prototaip → menguji → menerbitkan di GitHub & Vercel. Anda tidak perlu tahu pengaturcaraan.',
    guideDownloadTitle: 'Muat Turun Prompt Guide v24 (.md)',
    guideDownloadDesc: 'Muat turun fail SIMBOT_UNIVERSAL_PROMPT_GUIDE_V24.md ke peranti atau buka dalam tab baru. Fail ini ialah "otak" yang memandu keseluruhan perbualan dengan AI pada langkah-langkah seterusnya.',
    guideDownloadBtn: 'Muat Turun Prompt Guide v24 (.md)',
    guideUploadTitle: '2. Berikan fail kepada ChatGPT / Gemini',
    guideUploadDesc: 'Mulakan sembang baharu, muat naik fail atau tampal keseluruhan kandungan. AI mengenalinya sebagai pakej piawaian dan bermula automatik (AUTO-START).',
    guideQaTitle: '3. Berikan kawalan dan jawab soalan',
    guideQa1: 'AI memandu aliran kerja sendiri: ia bertanya dahulu, anda hanya menjawab ringkas apa yang anda tahu.',
    guideQa2: 'Tidak perlu mengarah "cipta simulasi" — fail itu sudah memperkasakan AI untuk bermula sendiri.',
    guideQa3: 'Anda tetap mengawal kandungan, pengetahuan sumber dan keputusan akhir.',
    guideQa4: 'AI membimbing satu langkah pada satu masa dan menunggu keputusan anda; ia meneruskan hanya apabila anda bersedia.',
    guideTipsTitle: '4. Cipta simulasi / permainan daripada fail asal',
    guideTip1: 'Daripada fail asal, anda boleh meminta AI menghasilkan fail .md berasingan (ROM) untuk setiap pelajaran, permainan, atau rancangan pengajaran.',
    guideTip2: 'AI menulis ROM cukup terperinci supaya ejen pengekodan boleh melaksanakannya tanpa meneka.',
    guideTip3: 'Simulasi, permainan, dan rancangan pengajaran kedua-duanya melalui rantaian yang sama: idea → ROM → prototaip → uji → terbitkan.',
    guideToolsTitle: 'Alat: AI Studio → GitHub → Vercel',
    guideToolsDesc: 'Tiga alat percuma yang mengiringi laluan — Langkah 5 AI Studio membina aplikasi, Langkah 7 GitHub menyimpan kod, Langkah 8 Vercel menerbit pautan web:',
    guideToolStudio: 'Google AI Studio',
    guideToolStudioDesc: 'Langkah 5 – Tempat muat fail .md baru, pilih Web App, klik Build untuk mencipta aplikasi interaktif yang berjalan terus.',
    guideToolGit: 'GitHub',
    guideToolGitDesc: 'Langkah 7 – Tempat simpan kod sumber dalam repository Public untuk sedia diterbit.',
    guideToolVercel: 'Vercel',
    guideToolVercelDesc: 'Langkah 8 – Sambung repository GitHub, bina dan beri pautan web dikongsi.',
    guideToolStudioSignup: 'Gunakan akaun Google percuma anda untuk log masuk AI Studio. Ingat gunakan EMAIL SAMA ini untuk GitHub dan Vercel.',
    guideToolStudioLogin: 'Layari aistudio.google.com → klik "Sign in" → pilih akaun Google anda untuk masuk ke halaman utama.',
    guideToolGitSignup: 'Buat akaun di github.com/signup menggunakan EMAIL SAMA yang digunakan untuk AI Studio — sahkan melalui peti masuk.',
    guideToolGitLogin: 'Buka github.com → klik "Sign in" → masukkan email/nama pengguna dan kata laluan. Sebaiknya aktifkan pengesahan dua faktor (2FA).',
