    qrGenerating: 'Gumagawa ng QR code...',
    guideTab: 'Gabay',
    guideTabTitle: 'Gumawa ng interaktibong produkto sa pagtuturo at pagkatuto gamit ang AI',
    guideTitle: 'Lumikha ng interaktibong produkto sa pagtuturo at pagkatuto',
    guideIntro: 'Hindi basta "gumagana" — kailangang lumikha ng mahalagang karanasan sa pagkatuto. Ang sukat sa huli: halaga ng pagkatuto, HINDI ang pagiging kumplikado ng teknolohiya. 8 hakbang na landas (Hakbang 1–Hakbang 8) sa isang sesyon: mula sa tunay na problema sa pagkatuto ng mga estudyante hanggang sa shared web link. Hindi kailangan marunong mag-program – sapat na ang ideya sa pagtuturo!',
    guideStep1T: 'Hakbang 1 • Tukuyin ang problema at anyo',
    guideStep1D: 'Pumili ng ISANG partikular na aralin, sabihin ang totoong hirap ng mga estudyante (maunawaan? makita? magsanay? maranasan?), pinagmulan ng kaalaman at layunin ng pagkatuto. Pumili ng ISANG pangunahing anyo: simulation, interaktibong modelo, laro, gamification, virtual lab, sitwasyong may desisyon. Resulta: papel ng paglalarawan Problema – Layunin – Anyo.',
    guideStep2T: 'Hakbang 2 • Mangalap ng impormasyon (dalawang koponan)',
    guideStep2D: 'Hatiin ang grupo sa dalawang koponan. Ang koponan sa mesa ay gumaganap bilang ESTUDYANTE: isulat ang nararamdaman kapag mahirap unawain ang aralin, sabihin ang mga hiling, magmungkahi ng masaya at madaling paraan ng pagkatuto. Ang koponang gumagala ay gumaganap bilang GURO: mabilis na magtanong sa ibang grupo, itala ang magagandang sagot, dalhin pabalik. Round 1 • 5 minuto → palitan → Round 2 • 5 minuto.',
    guideStep3T: 'Hakbang 3 • Buuin at i-download ang Prompt Guide',
    guideStep3D: 'Pagsama-samahin ang mga papel, pagkasunduan ang ISANG paksa na pinaka-kailangan ng mga estudyante; isulat ang maikling deskripsyon ng aralin (baitang, aralin, layunin, kahirapan). I-download ang Prompt Guide v24 (.md) sa webshare-pmca.vercel.app papunta sa iyong device.',
    guideStep4T: 'Hakbang 4 • Bigyan ng kapangyarihan ang AI',
    guideStep4D: 'Buksan ang ChatGPT o Gemini (sapat na ang libreng bersyon). Ipadala ang .md file at bigyan ng kapangyarihan: "Sundin ang dokumento, itanong sa akin kung kinakailangan". Sagutin ang mga tanong ng AI nang buo at totoo hangga’t maaari. Resulta: 01 BAGONG .md file — blueprint ng disenyo para sa AI Studio (hal.: SIM_DINH_LUAT_I_NEWTON_SPEC.md).',
    guideStep5T: 'Hakbang 5 • Gumawa ng app gamit ang AI Studio',
    guideStep5D: 'Buksan ang Google AI Studio, mag-sign in gamit ang Google account. I-load ang buong nilalaman ng bagong .md file sa command box. Piliin ang Web App at i-click ang Build — isinusulat ng AI ang code, subukan mong patakbuhin. Tingnan ang preview at magbigay ng mga karagdagang utos hanggang masiyahan. Resulta: interaktibong app na GUMAGANA kaagad sa AI Studio.',
    guideStep6T: 'Hakbang 6 • Subukan at pagbutihin',
    guideStep6D: 'Bubukas kaagad sa browser (kabilang ang phone), alam agad ng mga estudyante kung ano ang gagawin, may feedback na tama/mali/iskor/mungkahi, tama ang nilalaman sa pamantayan ng subject. Hindi pa nasiyahan? Magbigay ng karagdagang utos para ayusin kaagad sa AI Studio — hindi kailangan marunong mag-program.',
    guideStep7T: 'Hakbang 7 • I-save ang code sa GitHub',
    guideStep7D: 'AI Studio → Export / Get Code para i-download ang code sa device. GitHub → New repository, bigyan ng malinaw na pangalan (hal.: ai-quiz-lop5), piliin ang Public. GitHub → Upload files: i-drag ang lahat ng code files → Commit changes. Paalala: gumamit ng ISANG email para sa AI Studio, GitHub at Vercel.',
    guideStep8T: 'Hakbang 8 • I-publish ang web link (Vercel)',
    guideStep8D: 'Vercel → Add New Project, ikonekta ang GitHub account → Import repository → piliin ang repo na kakagawa lang → Deploy. Bubuo ang Vercel at bibigyan ka ng link [pangalan].vercel.app — subukan sa phone. Mag-edit mamaya: hindi nagbabago ang link, awtomatikong nag-a-update ang Vercel.',
    guideControlTitle: 'Paano "kinokontrol" ng file na ito ang AI',
    guideControlText: 'Naglalaman ang gabay ng standard na proseso mula ideya hanggang web: pakinggan ang problema ng estudyante → magtipon ng source knowledge → tukuyin ang mga layunin → idisenyo ang karanasan → isulat ang ROM → gumawa ng prototype → subukan → i-publish sa GitHub & Vercel. Hindi mo kailangang marunong mag-program.',
    guideDownloadTitle: 'I-download ang Prompt Guide v24 (.md)',
    guideDownloadDesc: 'I-download ang file na SIMBOT_UNIVERSAL_PROMPT_GUIDE_V24.md sa device o buksan sa bagong tab. Ang file na ito ang "utak" na gumagabay sa buong pag-uusap sa AI sa mga susunod na hakbang.',
    guideDownloadBtn: 'I-download ang Prompt Guide v24 (.md)',
    guideUploadTitle: '2. Ibigay ang file sa ChatGPT / Gemini',
    guideUploadDesc: 'Magsimula ng bagong chat, i-upload ang file o i-paste ang buong laman. Makikilala ito ng AI bilang standards pack at magsisimula ito nang awtomatiko (AUTO-START).',
    guideQaTitle: '3. Ibigay ang kontrol at sagutin ang mga tanong',
    guideQa1: 'Ang AI ang nagmamaneho ng workflow: ito ang unang nagtatanong, sasagot ka lang nang maikli kung ano ang alam mo.',
    guideQa2: 'Hindi mo kailangang mag-utos na "gumawa ng simulation" — ang file na ang nagbigay-kapangyarihan sa AI na magsimula nang mag-isa.',
    guideQa3: 'Ikaw pa rin ang kumokontrol sa content, source knowledge, at mga huling desisyon.',
    guideQa4: 'Ginagabayan ka ng AI nang paisa-isa at naghihintay sa iyong resulta; magpapatuloy lang ito kapag handa ka na.',
    guideTipsTitle: '4. Gumawa ng simulation / game mula sa orihinal na file',
    guideTip1: 'Mula sa orihinal na file, maaari mong hilingin sa AI na gumawa ng mga hiwalay na .md file (ROM) para sa bawat aralin, laro, o banghay-aralin.',
    guideTip2: 'Isusulat ng AI ang ROM nang sapat ang detalye para ma-implement ito ng coding agent nang hindi naghuhula.',
    guideTip3: 'Ang simulation, game, at banghay-aralin ay dumadaan sa parehong chain: ideya → ROM → prototype → subukan → i-publish.',
    guideToolsTitle: 'Mga tool: AI Studio → GitHub → Vercel',
    guideToolsDesc: 'Tatlong libreng tool sa daan — Hakbang 5 gumagawa ang AI Studio ng app, Hakbang 7 iniimbak ng GitHub ang code, Hakbang 8 inilalathala ng Vercel ang web link:',
    guideToolStudio: 'Google AI Studio',
    guideToolStudioDesc: 'Hakbang 5 – Lugar para i-load ang bagong .md file, piliin ang Web App, i-click ang Build para gumawa ng interaktibong app na gumagana kaagad.',
    guideToolGit: 'GitHub',
    guideToolGitDesc: 'Hakbang 7 – Lugar para iimbak ang source code sa Public repository para handa nang mai-publish.',
    guideToolVercel: 'Vercel',
    guideToolVercelDesc: 'Hakbang 8 – Ikonekta ang GitHub repository, bubuo at bibigyan ng shared web link.',
    guideToolStudioSignup: 'Gamitin ang libreng Google account mo para mag-sign in sa AI Studio. Tandaan gamitin ang PAREHONG EMAIL na ito para sa GitHub at Vercel.',
    guideToolStudioLogin: 'Pumunta sa aistudio.google.com → i-click ang "Sign in" → piliin ang Google account mo para pumasok sa pangunahing pahina.',
    guideToolGitSignup: 'Gumawa ng account sa github.com/signup gamit ang PAREHONG EMAIL na ginamit sa AI Studio — i-verify sa iyong inbox.',
    guideToolGitLogin: 'Buksan ang github.com → i-click ang "Sign in" → ilagay ang email/username at password. Pinakamabuting paganahin ang two-factor authentication (2FA).',
    guideToolVercelSignup: 'Gumawa ng account sa vercel.com → i-click ang "Sign Up" → pinakamabuting piliin ang "Continue with GitHub" para ma-link kaagad (parehong shared email).',
    guideToolVercelLogin: 'Pumunta sa vercel.com → i-click ang "Log In" → mag-sign in sa GitHub/GitLab/Email na tumutugma sa account na ginawa.',
