    amAutoSyncNew: 'Sinkroniza automáticu bainhira iha post foun',
    amLastSync: 'Sinkronizasaun ikus: ',
    qrGenerating: 'Kria kódigu QR...',
    guideTab: 'Manual',
    guideTabTitle: 'Kria produtu ensino-aprende interativu ho AI',
    guideTitle: 'Kria produtu aprendizajen-interativa',
    guideIntro: 'La’os de’it "bele ran" — maibé tenki kria esperiensia aprendizajen ne’ebé iha valór. Medida ikus: valór aprendizajen, LA’OS komplikasaun teknolojia. Dalan 8 pasu (Pasu 1–Pasu 8) iha sesaun ida: husi problema aprendizajen loos husi estudante sira to’o link web atu fahe. La presiza hatene programasaun – presiza de’it idea pedagójika!',
    guideStep1T: 'Pasu 1 • Identifika problema no formatu',
    guideStep1D: 'Hili lisaun espesífiku ida, hatán difikuldade loos estudante nian (komprende? haree? prátika? esperiénsia?), fonte koñesimentu no objetivu aprendizajen. Hili formatu prinsipál ida: simulasaun, modelu interativu, jogu, jogu-ifikasaun, laboratóriu virtuál, senáriu desizaun. Rezultadu: folha deskrisaun Problema – Objetivu – Formatu.',
    guideStep2T: 'Pasu 2 • Koleita informasaun (ekipa rua)',
    guideStep2D: 'Fahe grupu ba ekipa rua. Ekipa iha meza atua hanesan ESTUDANTE: hakerek sentimentu bainhira aprende susar atu komprende, hateten deseju sira, sujere maneira aprende divertidu no fasil. Ekipa la’o atua hanesan PROFESÓR: husu lalais grupu seluk, hakerek resposta di’ak sira, lori fila. Ronda 1 • 5 minutu → mudansa → Ronda 2 • 5 minutu.',
    guideStep3T: 'Pasu 3 • Sintetiza no download Prompt Guide',
    guideStep3D: 'Fou’ou folha sira, konkorda ida tópiku ne’ebé estudante presiza liu; hakerek deskrisaun lisaun badak (klase, lisaun, objetivu, difikuldade). Download Prompt Guide v24 (.md) iha webshare-pmca.vercel.app ba ita-nia aparelhu.',
    guideStep4T: 'Pasu 4 • Fó podér ba AI',
    guideStep4D: 'Loke ChatGPT ka Gemini (versaun grátis ona asu). Haruka .md file no fó podér: "Tuir dokumentu, husu ha’u se presiza". Responde pergunta AI nian kompletu no loos tuir matenek. Rezultadu: .md file ida FÓU — planu dezign ba AI Studio (ez.: SIM_DINH_LUAT_I_NEWTON_SPEC.md).',
    guideStep5T: 'Pasu 5 • Kria app ho AI Studio',
    guideStep5D: 'Loke Google AI Studio, login ho konta Google. Karrega konteúdu hotu husi .md file foun ba kaixa komandu. Hili Web App depois klik Build — AI hakerek kódigu rasik, ita koko halai. Haree preview no fó komandu tan to’o kontente. Rezultadu: app interativu ne’ebé RAN kedas iha AI Studio.',
    guideStep6T: 'Pasu 6 • Testa no hadi’ak',
    guideStep6D: 'Loke kedas iha browser (inklui telemóvel), estudante sira hatene kedas saida atu halo, iha feedback loos/sala/pontu/sujestaun, konteúdu tuir padraun materiál. Sei la kontente? Fó komandu tan atu hadi’a kedas iha AI Studio — la presiza hatene programasaun.',
    guideStep7T: 'Pasu 7 • Rai kódigu iha GitHub',
    guideStep7D: 'AI Studio → Export / Get Code atu download kódigu ba aparelhu. GitHub → New repository, fó naran klaru (ez.: ai-quiz-lop5), hili Public. GitHub → Upload files: dada kódigu hotu ba laran → Commit changes. Nota: uza EMAIL ida de’it ba AI Studio, GitHub no Vercel.',
    guideStep8T: 'Pasu 8 • Publika link web (Vercel)',
    guideStep8D: 'Vercel → Add New Project, liga konta GitHub → Import repository → hili repo foun ne’ebé kria → Deploy. Vercel harii rasik no fó link [katan].vercel.app — koko loke iha telemóvel. Hadia depois: link la muda, Vercel atualiza automátiku.',
    guideControlTitle: 'Oinsá ficheiru ne\'e "kontrola" AI',
    guideControlText: 'Ficheiru manual iha prosesu padraun husi ideia to\'o web: rona problema estudante → halibur koñesimentu husi fonte → define objetivu → dezenya esperiénsia → hakerek ROM → kria protótipo → testa → publika iha GitHub & Vercel. La presiza hatene programasaun.',
    guideDownloadTitle: 'Download Prompt Guide v24 (.md)',
    guideDownloadDesc: 'Download file SIMBOT_UNIVERSAL_PROMPT_GUIDE_V24.md ba aparelhu ka loke iha tab foun. File ida-ne’e "kakutak" ne’ebé manenek inteiru konversa ho AI iha pasu tuir mai.',
    guideDownloadBtn: 'Download Prompt Guide v24 (.md)',
    guideUploadTitle: '2. Fó ficheiru ba ChatGPT / Gemini',
    guideUploadDesc: 'Hahú konversa foun, upload ficheiru ka tau konteúdu tomak. AI rekoñese ne\'e pakote padraun no hahú automáticu (AUTO-START).',
    guideQaTitle: '3. Fó kontrola no hatán pergunta',
    guideQa1: 'AI mak lori prosesu rasik: nia husu uluk, ita de\'it hatán badak kona-ba buat ne\'ebé ita hatene.',
    guideQa2: 'La presiza haruka "kria simulasaun" — ficheiru ona fó empower ba AI atu hahú rasik.',
    guideQa3: 'Ita mak kontrola konteúdu, koñesimentu husi fonte, no desizaun finál.',
    guideQa4: 'AI orienta pasu ida-idak no hein ita-nia rezultadu; nia ba oin de\'it bainhira ita prontu.',
    guideTipsTitle: '4. Kria simulasaun / jogo husi ficheiru orijinál',
    guideTip1: 'Husi ficheiru orijinál, ita bele husu AI atu kria ficheiru .md separadu (ROM) ba lisaun ida-idak, jogo ida-idak, ka planu lisaun.',
    guideTip2: 'AI hakerek ROM ho detallu sufisiente atu coding agent bele implementa la\'ós haka\'ak desizaun.',
    guideTip3: 'Simulasaun, jogo, ka planu lisaun hotu-hotu liu husi kadeia ida: ideia → ROM → protótipo → testa → publika.',
    guideToolsTitle: 'Ferramenta: AI Studio → GitHub → Vercel',
    guideToolsDesc: 'Ferramenta grátis tolu tuir dalan — Pasu 5 AI Studio kria app, Pasu 7 GitHub rai kódigu, Pasu 8 Vercel publika link web:',
    guideToolStudio: 'Google AI Studio',
    guideToolStudioDesc: 'Pasu 5 – Fatín atu karrega .md file foun, hili Web App, klik Build atu kria app interativu ne’ebé ran kedas.',
    guideToolGit: 'GitHub',
    guideToolGitDesc: 'Pasu 7 – Fatín atu rai kódigu iha repository Public hodi prepara publiéa.',
