    guideToolStudioSignup: 'Uza ita-nia konta Google grátis atu login iha AI Studio. Lembra uza EMAIL IDA NE’EBÉ SAMA ba GitHub no Vercel.',
    guideToolStudioLogin: 'Bá aistudio.google.com → klik "Sign in" → hili ita-nia konta Google atu tama pájina prinsipál.',
    guideToolGitSignup: 'Kria konta iha github.com/signup ho EMAIL SAMA ne’ebé uza ba AI Studio — verifika liu husi ita-nia korreiu.',
